import { ComboChart, type ComboChartSeries } from '@absoluteui/components/combo-chart';

const series: ComboChartSeries[] = [
  { id: 'rev', label: 'Revenue', type: 'bar', values: [120, 150, 170, 160] },
  { id: 'margin', label: 'Margin', type: 'line', axis: 'secondary', values: [0.32, 0.4, 0.38, 0.41] },
];
const host = document.createElement('div');
document.body.append(host);
ComboChart.create(host, {
  label: 'Revenue and margin',
  categories: ['Q1', 'Q2', 'Q3', 'Q4'],
  series,
  primaryAxis: { label: 'Revenue (k)' },
  secondaryAxis: { label: 'Margin', format: { style: 'percent' } },
  crosshair: true,
});

import { ComboChart, type ComboChartSeries, type ComboChartZoomDetail } from '@absoluteui/components/combo-chart';

const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const series: ComboChartSeries[] = [
  { id: 'web', label: 'Web', type: 'bar', values: months.map((_, i) => 40 + i * 3) },
  { id: 'store', label: 'Store', type: 'bar', values: months.map((_, i) => 30 + (i % 4) * 5) },
  { id: 'target', label: 'Target', type: 'line', values: months.map(() => 90) },
];
const host = document.querySelector<HTMLElement>('#sales');
if (host) {
  const chart = ComboChart.create(host, { label: 'Sales by channel', categories: months, series, stacked: true, zoom: true, zoomRange: { from: 0, to: 2 } });
  host.addEventListener('aui-zoom', (event) => {
    const { x } = (event as CustomEvent<ComboChartZoomDetail>).detail;
    host.dataset.window = x ? `${months[Math.round(x.from)] ?? ''}-${months[Math.round(x.to)] ?? ''}` : 'all';
  });
  chart.update({ zoomRange: null });
}
